--============================================
--宝石摘除接口
--返回值 0:成功（低级宝石摘除符） 1:无此装备 2:宝石位置错误 3:装备上没有宝石 4:装备非法 8:需要宝石摘除符 9:成功（高级宝石摘除符）
--============================================
function x900011_ReomveProc(sceneId,selfId, EquipIndex, GemIndex, MatIndex)
	
	local equip_point = LuaFnGetBagEquipType(sceneId,selfId, EquipIndex)
	if equip_point == -1 then
		return 1
	elseif equip_point == 2 then --原有时装已替换为 2号位 留下此代码
		return 4
	end
	
	local gem_type = GetGemEmbededType(sceneId,selfId, EquipIndex, GemIndex)
--	AddGlobalCountNews( sceneId,"gem_type "..gem_type)
	if gem_type == 0 then
		return 3
	end
	if gem_type == -1 then
		return 4
	end
	local gem_index = LuaFnGetItemTableIndexByIndex( sceneId, selfId, MatIndex )
--	if equip_point == 16 then --时装特写 XYZ 20181218  原有时装已替换为 2号位 此处代码废弃
--		if LuaFnGetAvailableItemCount(sceneId, selfId,30503136) < 1then
--		    return 8
--		end
--	    LuaFnDelAvailableItem(sceneId,selfId,30503136,1)
--	    return 9
--	end
	if gem_index == 30900012 then  --低级宝石摘除符
		return 0
	elseif (gem_index >= 30900036 and gem_index <= 30900044) then  --高级宝石摘除符
		return 9
	else
		return 8
	end

end
--============================================
--宝石摘除接口
--宝石摘除后的相关处理（发送世界公告）
--============================================
function x900011_SplitGemSucceed(sceneId,selfId, EquipPos, GemPos, MatPos)
    --增加特效
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
		
    local CharmId = LuaFnGetItemTableIndexByIndex( sceneId, selfId, MatPos )
    --大于等于3级以上高级宝石摘除符使用摘除成功发出世界公告
    if (CharmId >= 30900038 and CharmId <= 30900044) then  --高级宝石摘除符
		   local PlayerName = GetName(sceneId,selfId)
		   local GemInfo = GetBagItemTransfer( sceneId, selfId, GemPos )
		   local MatInfo = GetBagItemTransfer( sceneId, selfId, MatPos )
	     str = format( "#H#{_INFOUSR%s}拿着#{_INFOMSG%s}嘴里念念有词，只见#{_INFOMSG%s}慢慢剥落，竟毫无损伤，真是极品之符啊！", PlayerName, MatInfo, GemInfo)
	     BroadMsgByChatPipe( sceneId, selfId, str, 4 )
	end
	x900011_RefreshEquipGemGrade(sceneId,selfId,EquipPos,GemPos) --宝石评分刷新
end
--============================================
--材料点金
--============================================
function x900011_MaterialLeveUpEx(sceneId,selfId,npcod,nPos1,nPos2)

	local nLevel = GetLevel(sceneId,selfId)
	if nLevel < 80 then
		x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_24}" )
	    return
	end
	if LuaFnGetMaterialBagSpace( sceneId, selfId ) < 1 then
		x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_20}" )
	    return
	end
	local nMaterialItem = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos1 )
	if nMaterialItem ~= 20501003 and nMaterialItem ~= 20501007 and nMaterialItem ~= 20502003 and nMaterialItem ~= 20502007 then
		x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_15}" )
	    return
	end
	local nMaterialItem_DJS = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos2 )
	if nMaterialItem_DJS ~= 38000952 then
		x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_14}" )
	    return
	end
	if GetMoney(sceneId,selfId) + GetMoneyJZ(sceneId,selfId) < x900011_g_SJ_CaiLiaoQiangHua_needJiaoZi then
		x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_25}" )
	    return
	end
	local nDJSNum = LuaFnGetAvailableItemCount(sceneId, selfId,nMaterialItem_DJS)
	if nDJSNum < 1 then
		x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_18}" )
	    return
	end
	local nFinalItem = 0
	local nMaterialItemNum = LuaFnGetAvailableItemCount(sceneId, selfId,nMaterialItem)
	if nMaterialItem == 20501003 then --棉布
		if nMaterialItemNum < 1 then
			x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_16}" )
			return
		end
		nFinalItem = 20501004
	elseif nMaterialItem == 20501007 then --绑定棉布
	    if nMaterialItemNum < 1 then
			x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_16}" )
			return
		end
		nFinalItem = 20501008
	elseif nMaterialItem == 20502003 then --秘银
	    if nMaterialItemNum < 1 then
			x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_16}" )
			return
		end
		nFinalItem = 20502004
	elseif nMaterialItem == 20502007 then --绑定秘银
	    if nMaterialItemNum < 1 then
			x900011_NotifyTips( sceneId, selfId, "#{ZZQH_180929_16}" )
			return
		end
		nFinalItem = 20502008
	end
	local Item = LuaFnDelAvailableItem(sceneId,selfId,nMaterialItem,1) --材料扣除
	local Itema = LuaFnDelAvailableItem(sceneId,selfId,nMaterialItem_DJS,1) --材料扣除
	 if Item ~= 1 or Itema~= 1 then
	    x900011_NotifyTips( sceneId, selfId, "物品扣除失败，请检查" )
	 return
	 end
	LuaFnCostMoneyWithPriority( sceneId, selfId,x900011_g_SJ_CaiLiaoQiangHua_needJiaoZi) --扣钱
	local pos = TryRecieveItem( sceneId, selfId,nFinalItem, 1 )
	 
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
	x900011_NotifyTips( sceneId, selfId, "您获得了1个"..GetItemName(sceneId,nFinalItem).."。" )	
	local strText = format("#P点石成金，至尊耀世！#{_INFOUSR%s}#P妙手生花，将1个%s#P点金成1个#{_INFOMSG%s}。",
					GetName(sceneId,selfId),
					GetItemName(sceneId,nMaterialItem),
					GetBagItemTransfer(sceneId,selfId,pos)) 
	AddGlobalCountNews(sceneId,strText);
end
--============================================
--刷新宝石评分数据
--============================================
function x900011_RefreshEquipGemGrade_Core(sceneId,selfId)
	local Grade = 0
    for i = 100,118 do
	    if i ~= 102 and i ~= 108 and i ~= 117 then 
			local _,Data = LuaFnGetItemCreator(sceneId, selfId, i)
			if Data ~= nil and Data ~= "" then
			    local pos1,pos2,Data = strfind(Data,"&BS(%d%d%d)") 
				if pos1 ~= nil and pos2 ~= nil then 
					if Data ~= nil then 
						Grade = Grade + tonumber(Data)
					end
				end
			end
		end
	end
	SetMissionData(sceneId,selfId,GEM_GRADE,Grade)
end
--============================================
--更新装备宝石相关评分
--注意：此处代码需在宝石镶嵌、摘除成功后使用
--EquipBagIndex bagpos01
--GemID 宝石编号
--GemPos 宝石位 仅限摘除时使用！！！
--============================================
function x900011_RefreshEquipGemGrade(sceneId,selfId,EquipBagIndex,GemPos)	
	--x900011_g_GemGrade
	local NowGemInfo = {} --宝石信息组
	local FinalData = ""
	local gemEmbededIdx
	local GemXiulian,GemJingJie = 0,0
	for i = 1,GetBagGemCount(sceneId,selfId,EquipBagIndex) do
		gemEmbededIdx = GetGemEmbededType( sceneId, selfId, EquipBagIndex, i-1 )  -----得到宝石编号
		if gemEmbededIdx ~= -1 and gemEmbededIdx ~= 0 then
			tinsert(NowGemInfo,gemEmbededIdx)
		end
	end
	
	for i = 1,getn(NowGemInfo) do --计算原有评分
		if x900011_g_GemGrade[NowGemInfo[i]] ~= nil then
			GemXiulian = GemXiulian + x900011_g_GemGrade[NowGemInfo[i]][1]
			GemJingJie = GemJingJie + x900011_g_GemGrade[NowGemInfo[i]][2]
		end
	end	
	if GemPos ~= nil then --处理摘除时的特殊情况！！！
	    local Gem_SplitID = LuaFnGetItemTableIndexByIndex( sceneId, selfId, GemPos )
		GemXiulian = GemXiulian - x900011_g_GemGrade[Gem_SplitID][1]
		GemJingJie = GemJingJie - x900011_g_GemGrade[Gem_SplitID][2]
	end

	--*************************************************
	--Q仅供娱乐，切勿商用修复，这里逍遥子写的有点bug
	--*************************************************
end
