--============================================
function x900011_Cloth_SplitGem(sceneId,selfId,ClothPos,nSelect)--这里开始全部重写

	--ADD 20190226 没有空间将会死循环
	local EquipPoint = LuaFnGetBagEquipType( sceneId, selfId, ClothPos )
	if EquipPoint ~= 2 then
		x900011_NotifyTips( sceneId, selfId, "#{SZPR_091023_45}" )
		return
	end
	local materbagspace = LuaFnGetMaterialBagSpace( sceneId, selfId)  -----得到材料栏空间
	if materbagspace < 1 or LuaFnGetPropertyBagSpace( sceneId, selfId ) < 1 then
		x900011_NotifyTips( sceneId, selfId,"道具栏和材料栏至少需要1个空位" )
		return 		 
	end
	--ADD 20190226
	if nSelect < 0 or nSelect > 3 then
		x900011_NotifyTips( sceneId, selfId, "数据错误，请不要随意修改客户端" )
	    return
	end
	local Available1 = LuaFnIsItemAvailable(sceneId, selfId, ClothPos)
	if Available1 < 1 then
		x900011_NotifyTips( sceneId, selfId, "#{SZPR_091023_45}" )
	    return
	end
	if LuaFnGetAvailableItemCount(sceneId, selfId,30503136) < 1 then
	    x900011_NotifyTips( sceneId, selfId, "#{SZPR_091023_80}" )
	    return
	end
	if LuaFnGetMaterialBagSpace( sceneId, selfId ) < 1 then
	    x900011_NotifyTips( sceneId, selfId, "#H背包材料栏空位不足1个，无法进行配饰清除。" )
	   return
	end
	local ClothItem = GetItemTableIndexByIndex(sceneId, selfId, ClothPos)
	
