function GetClothGemType(GemID)
    local GemType = mod(GemID,100)
	if GemType >=1 and GemType <= 11 then
	    return 1,GemType
	elseif GemType >=12 and GemType <= 22 then
		return 2,GemType
	elseif GemType >=23 and GemType <= 33 then
		return 3,GemType
	else
		return 0,0
	end
end
