	local EquipPoint = LuaFnGetBagEquipType( sceneId, selfId, pos1 )
	if EquipPoint ~= 2 then
		x900011_NotifyTips( sceneId, selfId, "你放入的不是时装" )
		return
	end
	local equipEmbededGemCount = 0
	local nSign = "&DZ("..strrep("%d",8)..")".."(%w)".."("..strrep("%d",8)..")".."(%w)".."("..strrep("%d",8)..")"
	local _,GemMsg_Data = LuaFnGetItemCreator( sceneId, selfId, pos1)--取得当前镶嵌信息
	if GemMsg_Data ~= nil and GemMsg_Data ~= "" then
		local nGemPos_1,nGemPos_2,nGemID_1,_,nGemID_2,_,nGemID_3 = strfind(GemMsg_Data,nSign)
		local GemMsg = {}--LuaSplit(GemMsg_Data,",")
		if nGemPos_1 ~= nil and nGemPos_2 ~= nil then
			GemMsg[1] = nGemID_1
			GemMsg[2] = nGemID_2
			GemMsg[3] = nGemID_3
		end
		for i = 1,getn(GemMsg) do
			if GemMsg[i] ~= nil and GemMsg[i] ~= "" then
				if tonumber(GemMsg[i]) ~= 0 then
					equipEmbededGemCount = equipEmbededGemCount + 1
				end
			end
		end
	else
		equipEmbededGemCount = 0
	end
	--local equipEmbededGemCount = GetGemEmbededCount( sceneId, selfId, pos1 ) --新写法
	local GemPos = pos2
--	if equipEmbededGemCount == 0 then --直接走默认流程
--	    GemPos = pos2
--	end
--	if equipEmbededGemCount == 1 then
--	    GemPos = pos3
--	end
--	if equipEmbededGemCount == 2 then
--	    GemPos = pos4
--	end
	--////////////ADD 20190227 这样方便修正
	--x900011_NotifyTips( sceneId, selfId, equipEmbededGemCount )
	if equipEmbededGemCount >= 1 then--直接新系统走起
	    x900011_SetNewClothGem(sceneId,selfId,pos1,GemPos)
		return
	end
	--////////////
	local Available1 = LuaFnIsItemAvailable(sceneId, selfId, pos1)
	local Available2 = LuaFnIsItemAvailable(sceneId, selfId, GemPos)
	if Available1 < 1  or Available2 < 1 then
		x900011_NotifyTips( sceneId, selfId, "这里只能放入时装！" )
	    return
	end
	local ClothItem = GetItemTableIndexByIndex(sceneId, selfId, pos1)
	local GemItem = GetItemTableIndexByIndex(sceneId, selfId, GemPos)
	if LuaFnIsItemLocked(sceneId, selfId, pos1) ~= 0 or LuaFnIsItemLocked(sceneId, selfId, GemPos) ~= 0 then
		x900011_NotifyTips( sceneId, selfId, "时装点缀材料或时装已经加了锁" )
		return
	end
	local EquipPoint = GetItemEquipPoint( ClothItem )
	local equipType = LuaFnGetBagEquipType( sceneId, selfId, pos1 )
	if EquipPoint~=2 or equipType ~= 2 then--20190226修正
		x900011_NotifyTips( sceneId, selfId, "这里只能放入时装进行点缀！" )
		return
	end
	--检查绑定状态
	local GemIsBind = 0
	local nItemIdBind = LuaFnGetItemBindStatus(sceneId, selfId, pos1)
	local nItemIdBind2 = LuaFnGetItemBindStatus(sceneId, selfId, GemPos)
	if nItemIdBind == 1 or nItemIdBind2 == 1 then
		GemIsBind = 1;
	end
	local equipMaxGemCount = GetBagGemCount( sceneId, selfId, pos1 )
	if equipMaxGemCount < 1 then
		x900011_NotifyTips( sceneId, selfId, "该时装还未在洛阳（345，270）伊天彩处裁剪" )
		return
	end
	if equipMaxGemCount > equipEmbededGemCount and equipEmbededGemCount >= 3 then
        x900011_NotifyTips( sceneId, selfId, "时装点缀已经上限，不能再继续点缀"  )  
		return
	end
	
	if equipMaxGemCount <= equipEmbededGemCount or equipEmbededGemCount >= 3 then
	    x900011_NotifyTips( sceneId, selfId, "时装点缀已经上限，不能再继续点缀"   ) 
		return
	end
	
	local gemType = LuaFnGetItemType( GemItem )
	if not x900011_g_EquipGemTable[equipType] then
	    x900011_NotifyTips( sceneId, selfId, "此时装不能点缀"  )
		return
	end
	local passFlag = 0
	for i, gt in x900011_g_EquipGemTable[equipType] do
		if gt == gemType then
			passFlag = 1
			break
		end
	end
--	if passFlag == 0 then
--	    x900011_NotifyTips( sceneId, selfId, "此配饰不能点缀在时装上" )
--		return
--	end
    local gemIdx = LuaFnGetItemTableIndexByIndex( sceneId, selfId, GemPos )
	if x900011_g_GemGrade[gemIdx] ~= nil then
		x900011_NotifyTips( sceneId, selfId, "#{SZPR_091023_48}" )
		return
	end
	local szTransferItem = GetBagItemTransfer(sceneId,selfId,GemPos)
	local delitem1 = LuaFnDelAvailableItem(sceneId,selfId,30503135,1)
	if delitem1 ~= 1 then
		x900011_NotifyTips( sceneId, selfId, "时装配饰点缀符扣除失败，或者请检查你的背包其是否被加锁！" )
		return
	end
	local ret = GemEnchasing( sceneId, selfId, GemPos, pos1 )
	if ret and ret == 0 then
		if(GemIsBind == 1 ) then
			LuaFnItemBind( sceneId, selfId, pos1);
		end
		--////////////20190227 ADD
		--190520修正，因为蜜语金丝的缘故，这里默认的数据全部置前处理
		local nFinalData = ""
		if GemMsg_Data == nil then
			nFinalData = "&DZ"..tostring(gemIdx).."X00000000X00000000"
		else
			nFinalData = "&DZ"..tostring(gemIdx).."X00000000X00000000"..GemMsg_Data--gsub(GemMsg_Data,nSign,"&DZ"..tostring(gemIdx).."X00000000X00000000")
		end
		LuaFnSetItemCreator( sceneId, selfId, pos1, nFinalData)
		--////////////
		LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
		local name = GetName( sceneId, selfId )
		local szTransferEquip = GetBagItemTransfer( sceneId, selfId, pos1 )
		local message = format("#W#{_INFOUSR%s}#H向#W#{_INFOMSG%s}#H点缀了配饰#W#{_INFOMSG%s}#H时装瞬间变得光彩夺目。", name, szTransferEquip, szTransferItem);
		if (message ~= nil) then
			BroadMsgByChatPipe( sceneId, selfId, message, 4 )
		end
		x900011_NotifyTips( sceneId, selfId, "恭喜您，时装点缀成功！"  )
    else
        x900011_NotifyTips( sceneId, selfId, "时装点缀出现错误！请联系逍遥纪运营团队！"  )
		return
	end
end
