--时装打孔系统
--============================================
function x900011_Cloth_Split(sceneId,selfId,pos)
	local nItemId = GetItemTableIndexByIndex(sceneId, selfId, pos)
	local EquipPoint = LuaFnGetBagEquipType( sceneId, selfId, pos )
	if EquipPoint ~= 2 then --20190226修正
		x900011_NotifyTips( sceneId, selfId, "你放入的不是时装" )
		return
	end
	local Bore_Count = GetBagGemCount( sceneId, selfId, pos )
	if 	Bore_Count >= 3 then
		x900011_NotifyTips( sceneId, selfId, "该时装点缀位数已达最大" )
		return
	end
	local item1 = LuaFnGetAvailableItemCount(sceneId, selfId, 30503134)
	if item1 < 1 then
		x900011_NotifyTips( sceneId, selfId, "你身上缺少金梭，或已经加锁" )
		return
	end
	local delitem1 = LuaFnDelAvailableItem(sceneId,selfId,30503134,1)
		if delitem1 < 1 then
		x900011_NotifyTips( sceneId, selfId, "扣除材料失败" )
		return
	end
	local NeedMoney = 2000
	if AddMoney(sceneId,selfId, -NeedMoney) ~= 1 then
		x900011_NotifyTips( sceneId, selfId,"金钱不足。")
		return
	end
	AddBagItemSlot( sceneId, selfId, pos )
	local nowBore_Count =  GetBagGemCount( sceneId, selfId, pos )
	while nowBore_Count - Bore_Count ~= 1 do
		AddBagItemSlot( sceneId, selfId, pos )
		nowBore_Count =  GetBagGemCount( sceneId, selfId, pos )
	end
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
	local name = GetName( sceneId, selfId )
	local szTransferEquip = GetBagItemTransfer( sceneId, selfId, pos )
	local message = format("#W#{_INFOUSR%s}#H消耗了一个#W#{_ITEM30503134}#H为#W#{_INFOMSG%s}#H增加点缀位数", name,szTransferEquip );
	if (message ~= nil) then
		BroadMsgByChatPipe( sceneId, selfId, message, 4 )
	end
	x900011_NotifyTips( sceneId, selfId, "恭喜您，裁剪时装成功！"  )
	BeginUICommand( sceneId )
	UICommand_AddInt( sceneId, selfId ) --这里为target占位
	UICommand_AddInt( sceneId, 1 )
	EndUICommand( sceneId )
	DispatchUICommand( sceneId, selfId,  20091027)
	return
end
