--冥晶石分离系统
--============================================
function x900011_OnDoubleGemfenli( sceneId, selfId, g_GemItemPos, g_fenlifuPos)
	local nMaterialID = GetItemTableIndexByIndex(sceneId, selfId, g_fenlifuPos)
	if nMaterialID ~= 38000447 and nMaterialID ~= 38000448 then
		x900011_NotifyTips( sceneId, selfId,"#{BSZK_121012_57}" )
		return
	end
	if LuaFnIsItemLocked(sceneId, selfId, g_GemItemPos) ~= 0 then
		x900011_NotifyTips( sceneId, selfId,"#{BSZK_121012_17}" )
		return	
	end
	local nGemItemID = GetItemTableIndexByIndex(sceneId, selfId, g_GemItemPos)
	local nMainID, nAssistID, nAssistCount = LuaFnGetDoubleGemInfobyID(nGemItemID)
	if nMainID == 0 then
		x900011_NotifyTips( sceneId, selfId,"#{BSZK_121012_37}" )
		return	
	end
	local nNeedSpaceMater = 1 + nAssistCount
    if LuaFnGetMaterialBagSpace( sceneId, selfId ) < nNeedSpaceMater then
		x900011_NotifyTips( sceneId, selfId,"您的背包空间不足，请至少保留"..nNeedSpaceMater.."个材料栏与1个道具栏空位。" )
		return	
    end
    if LuaFnGetPropertyBagSpace( sceneId, selfId ) < 1 then
		x900011_NotifyTips( sceneId, selfId,"您的背包空间不足，请至少保留"..nNeedSpaceMater.."个材料栏与1个道具栏空位。" )
		return	
    end
	local nMoneySelf = GetMoney(sceneId,selfId) + GetMoneyJZ(sceneId,selfId)
	if nMoneySelf < x900011_g_DoubleMoney then
        x900011_NotifyTips( sceneId, selfId,  "#{BSZK_121012_39}" )
        return
	end
	local nIsBind = 0 --看看是不是该绑定起来
	if LuaFnGetItemBindStatus(sceneId,selfId,g_fenlifuPos) == 1 or LuaFnGetItemBindStatus(sceneId,selfId,g_GemItemPos) == 1 then
		nIsBind = 1
	end
	--开始正式流程了
	local nOldTrans = GetBagItemTransfer(sceneId,selfId,g_GemItemPos)
	LuaFnCostMoneyWithPriority( sceneId, selfId, x900011_g_DoubleMoney)
	local ret = LuaFnDelAvailableItem(sceneId,selfId,nMaterialID,1)--扣除分离符
	 if ret ~= 1 then
	 return
	 end
	--LuaFnDelAvailableItem(sceneId,selfId,nGemItemID,1)--扣除冥晶石
	LuaFnEraseItem( sceneId, selfId, g_GemItemPos )
	--发奖
	local nNewPos_M = TryRecieveItem(sceneId,selfId,nMainID,1)
	local nNewPos_A = 0
	for i = 1,nAssistCount do
		nNewPos_A = TryRecieveItem(sceneId,selfId,nAssistID,1)
		if nIsBind == 1 then
			LuaFnItemBind(sceneId,selfId,nNewPos_A)
		end
	end
	local nNewPos_C = TryRecieveItem(sceneId,selfId,38000446,1)
	if nIsBind == 1 then
		LuaFnItemBind(sceneId,selfId,nNewPos_M)
		LuaFnItemBind(sceneId,selfId,nNewPos_C)
	end
	x900011_NotifyTips( sceneId, selfId,  "成功分离，获得了"..nAssistCount.."颗"..GetItemName(sceneId,nAssistID).."。" )
	x900011_NotifyTips( sceneId, selfId,  "#{BSZK_121012_41}" )
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
	local nMessage = ""
	nMessage = format("#{_INFOUSR%s}#H小心翼翼的从#{_INFOMSG%s}#H上将#Y%s#H分离下来，并完好无损的获得了#Y%s#H颗#Y%s#H与一个#Y宝石琢刻符#H。",
						GetName(sceneId,selfId),
						nOldTrans,
						GetItemName(sceneId,nMainID),
						nAssistCount,
						GetItemName(sceneId,nAssistID))
	BroadMsgByChatPipe(sceneId, selfId, nMessage, 4)
end
