--============================================
function x900011_OnDoubleGemzhuoke( sceneId, selfId, Gemzhuoke_MainID, Gemzhuoke_AssistID, Gemzhuoke_MaterPos)
	if not Gemzhuoke_MainID or not Gemzhuoke_AssistID  or not Gemzhuoke_MaterPos then
		return
	end
	if LuaFnIsItemLocked(sceneId, selfId, Gemzhuoke_MaterPos) ~= 0 then
		x900011_NotifyTips( sceneId, selfId,"#{BSZK_121012_17}" )
		return	
	end
	local nMaterialID = GetItemTableIndexByIndex(sceneId, selfId, Gemzhuoke_MaterPos)
	if nMaterialID ~= 38000446 and nMaterialID ~= 38000445 then
		x900011_NotifyTips( sceneId, selfId,"#{BSZK_121012_24}" )
		return	
	end
	local nMoneyJZ = GetMoneyJZ(sceneId,selfId)
	local nMoneyJB = GetMoney(sceneId,selfId)
	local nMoneySelf = nMoneyJZ + nMoneyJB
	if nMoneySelf < x900011_g_DoubleMoney then
        x900011_NotifyTips( sceneId, selfId,  "#{BSZK_121012_29}" )
        return
	end
	local nAssistGemCount, nProductID = LuaFnGetDoubleGemInfo(Gemzhuoke_MainID, Gemzhuoke_AssistID)
	if nProductID == 0 then
		x900011_NotifyTips( sceneId, selfId,  "#{BSZK_121012_23}" )
		x900011_NotifyTips( sceneId, selfId,  "温馨提示：".."#{BSZK_121012_15}" )
        return
	end
	local nHaveCount = LuaFnGetAvailableItemCount(sceneId, selfId,Gemzhuoke_AssistID)
	if nHaveCount < nAssistGemCount then
		x900011_NotifyTips( sceneId, selfId,  "#{BSZK_121012_27}" )
        return
	end
	if LuaFnGetAvailableItemCount(sceneId, selfId,Gemzhuoke_MainID) < 1 then
		x900011_NotifyTips( sceneId, selfId,  "#{BSZK_121012_18}" )
        return
	end
	local nIsBind = 0 --看看是不是该绑定起来
	if LuaFnGetItemBindStatus(sceneId,selfId,Gemzhuoke_MaterPos) == 1 then
		nIsBind = 1
	end
	--开始正式流程
	LuaFnCostMoneyWithPriority( sceneId, selfId, x900011_g_DoubleMoney)
	local ret = LuaFnDelAvailableItem(sceneId,selfId,nMaterialID,1)--扣除琢刻符
	if ret ~= 1 then
	   return
	end
	local ret1 =LuaFnDelAvailableItem(sceneId,selfId,Gemzhuoke_MainID,1)--扣除抗性宝石
	if ret1 ~= 1 then
	   return
	end	
	local ret2 =LuaFnDelAvailableItem(sceneId,selfId,Gemzhuoke_AssistID,nAssistGemCount)--扣除属性宝石
	if ret2 ~= 1 then
	   return
	end	
	 
	local nNewPos = TryRecieveItem(sceneId,selfId,nProductID,1)
	if nIsBind == 1 then
		LuaFnItemBind(sceneId,selfId,nNewPos)
	end
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
	x900011_NotifyTips( sceneId, selfId,  "#{BSZK_121012_30}" )
	local nMessage = ""
	if nAssistGemCount == 3 then
		nMessage = format("#{_INFOUSR%s}#H极为小心的将三颗%s#H琢刻至%s#H内，光影流转中，却未曾料到这几块宝石竟然灵气相融，竟化作奇珍#{_INFOMSG%s}#H。",
						GetName(sceneId,selfId),
						GetItemName(sceneId,Gemzhuoke_AssistID),
						GetItemName(sceneId,Gemzhuoke_MainID),
						GetBagItemTransfer(sceneId,selfId,nNewPos))
	elseif nAssistGemCount == 4 then
		nMessage = format("#{_INFOUSR%s}#H极为小心的将四颗%s#H琢刻至%s#H内，光影流转中，却未曾料到这几块宝石竟然灵气相融，竟化作奇珍#{_INFOMSG%s}#H。",
						GetName(sceneId,selfId),
						GetItemName(sceneId,Gemzhuoke_AssistID),
						GetItemName(sceneId,Gemzhuoke_MainID),
						GetBagItemTransfer(sceneId,selfId,nNewPos))
	end
	BroadMsgByChatPipe(sceneId, selfId, nMessage, 4)
end
