function LuaFnGetDoubleGemInfo(nItemMainID,nAssistID)
	local nAssistGemCount, nProductID = 0,0
	for i = 1,getn(x900011_g_DoubleTable) do
		if x900011_g_DoubleTable[i][2] == nItemMainID and x900011_g_DoubleTable[i][3] == nAssistID then
			nAssistGemCount = x900011_g_DoubleTable[i][4]
			nProductID = x900011_g_DoubleTable[i][1]
		end
	end
	return nAssistGemCount, nProductID
end
function LuaFnGetDoubleGemInfobyID(itemID)
	local nMainID, nAssistID, nAssistCount = 0,0,0
	for i = 1,getn(x900011_g_DoubleTable) do
		if x900011_g_DoubleTable[i][1] == itemID then
			nMainID = x900011_g_DoubleTable[i][2]
			nAssistID = x900011_g_DoubleTable[i][3]
			nAssistCount = x900011_g_DoubleTable[i][4]
		end
	end
	return nMainID, nAssistID, nAssistCount
end
