--材料合成系统
--============================================
function x900011_MatirCompose(sceneId,selfId,g_CurNum_PerTime,nIndex,nSubIndex)
	--x900011_NotifyTips( sceneId, selfId, g_CurNum_PerTime.."  "..nIndex.."  "..nSubIndex )
	if nIndex < 0 or nIndex > 3 then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-1" )
	end
	
	if nSubIndex < 0 or nSubIndex > 4 then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-2" )
	end
	--整理合成数据
	local tSubData = x900011_CaiLiaoCompound_Data[nSubIndex]
	if tSubData == nil then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-3" )
		return
	end	
	
	local tItem = x900011_CaiLiaoCompound_Item[nIndex]
	if tItem == nil then
	    x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-4" )
		return
	end	
	
	local needCount = tSubData.needcount
	if needCount == nil or needCount <= 0 then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-5" )
		return
	end
	
	local needMoney = tSubData.needmoney
	if needMoney == nil or needMoney <= 0 then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-6" )
		return
	end
	
	local needLevel = tSubData.needlevel
	if needLevel == nil or needLevel <= 0 then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-7" )
		return
	end
	local needItemId = tItem[needLevel].nItemID1
	if needItemId == nil or needItemId <= 0 then
		--这里误报，暂时排除
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-8"..needItemId )
		return
	end
	
	local newLevel = tSubData.newlevel
	if newLevel == nil or newLevel <= 0 then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-9" )
		return
	end
	local newItemId = tItem[newLevel].nItemID1
	if newItemId == nil or newItemId <= 0 then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！-10" )
		return
	end
	local nHaveCount = LuaFnGetAvailableItemCount(sceneId, selfId,needItemId)
	if nHaveCount < needCount then
		x900011_NotifyTips( sceneId, selfId,  "对不起，你身上的"..tItem[needLevel].strShowName.."不足"..needCount.."个，无法继续进行" )
        return
	end
	local nCanCompoundNum = floor(nHaveCount / 5)
	if g_CurNum_PerTime > nCanCompoundNum then
		x900011_NotifyTips( sceneId, selfId,  "对不起，你身上的"..tItem[needLevel].strShowName.."不足以合成"..g_CurNum_PerTime.."个"..GetItemName(sceneId,newItemId))
        return
	end
	
	local nMoneyJZ = GetMoneyJZ(sceneId,selfId)
	local nMoneyJB = GetMoney(sceneId,selfId)
	local nMoneySelf = nMoneyJZ + nMoneyJB
	if nMoneySelf < tonumber(tSubData.needmoney) * g_CurNum_PerTime then
