function x900011_GemCompose(sceneId,selfId,g_GemTablePos,g_ItemBagIndex,nSel,g_CurrentOdds)
    --x900011_NotifyTips( sceneId, selfId, g_GemTablePos.."  "..g_ItemBagIndex.."   "..nSel.."   "..g_CurrentOdds )
	--g_GemTablePos
	--g_ItemBagIndex item
	--g_CurrentOdds 概率，可要可不要
	if nSel < 0 or nSel > 2 then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请不要非法修改客户端！" )
	end
	local itemId1 = LuaFnGetItemTableIndexByIndex( sceneId, selfId, g_GemTablePos )
	local itemId2 = LuaFnGetItemTableIndexByIndex( sceneId, selfId, g_ItemBagIndex )
	
	--x900011_NotifyTips( sceneId, selfId,itemId1.."  "..itemId2)
	if itemId1 < 50101001 or itemId1 > 50921409  then
        x900011_NotifyTips( sceneId, selfId,  "请先放入需要合成的宝石，再进行该操作。" )
		return
    end
	if itemId2 ~= 30900015 and itemId2 ~= 30900016 and itemId2 ~= 30900128  then
		x900011_NotifyTips( sceneId, selfId,  "ERROR "..g_ItemBagIndex )
		x900011_NotifyTips( sceneId, selfId,  "请先放入需要用作合成材料的宝石合成符，再进行该操作。" )
		return
	end
	local ret = LuaFnIsItemAvailable( sceneId, selfId, g_GemTablePos )
	if ret ~= 1 then
        x900011_NotifyTips( sceneId, selfId,  "该需要合成的宝石不可用，请检查背包！" )
		return
    end
	ret = LuaFnIsItemAvailable( sceneId, selfId, g_ItemBagIndex )
	if ret ~= 1 then
		x900011_NotifyTips( sceneId, selfId,  "该需要用作合成材料的宝石合成符不可用，请检查背包！" )
		return
	end
	local GemLevel = GetGemLevel(itemId1)
	--x900011_NotifyTips( sceneId, selfId,GemLevel)
	if GemLevel == 7 and itemId2 ~= 30900128 then --7级宝石合成的限制
		x900011_NotifyTips( sceneId, selfId,  "#{BSQHB_120830_07}" )
		return
	end
	if GemLevel >= 8 then --目前上限为8级
		x900011_NotifyTips( sceneId, selfId,  "#{BSQHB_120830_04}" )
		return
	end
	if x900011_g_RuleTable[GemLevel] == nil then
		x900011_NotifyTips( sceneId, selfId, "数据非法！请联系逍遥纪运营团队！" )
		return
	end
	local nMoneyJZ = GetMoneyJZ(sceneId,selfId)
	local nMoneyJB = GetMoney(sceneId,selfId)
	local nMoneySelf = nMoneyJZ + nMoneyJB
	if nMoneySelf < tonumber(x900011_g_RuleTable[GemLevel].MoneyCost) then
        x900011_NotifyTips( sceneId, selfId,  "对不起，你身上金钱不足，无法继续进行" )
        return
	end
	local nOdds = 0
	if nSel == 0 and x900011_g_RuleTable[GemLevel] ~= nil and x900011_g_RuleTable[GemLevel].CountTable[5] ~= nil then
		nOdds = x900011_g_RuleTable[GemLevel].CountTable[5].SuccOdds
		if g_ItemBagIndex ~= -1 then
			nOdds = x900011_g_RuleTable[GemLevel].CountTable[5].SuccOddsWithSpecStuff
		end	
	elseif nSel == 1 and x900011_g_RuleTable[GemLevel].CountTable[4] ~= nil  then
		nOdds = x900011_g_RuleTable[GemLevel].CountTable[4].SuccOdds
		if g_ItemBagIndex ~= -1 then
			nOdds = x900011_g_RuleTable[GemLevel].CountTable[4].SuccOddsWithSpecStuff
		end
	elseif nSel == 2 and x900011_g_RuleTable[GemLevel].CountTable[3] ~= nil then
		nOdds = x900011_g_RuleTable[GemLevel].CountTable[3].SuccOdds
		if g_ItemBagIndex ~= -1 then
			nOdds = x900011_g_RuleTable[GemLevel].CountTable[3].SuccOddsWithSpecStuff
		end
	end
    --x900011_NotifyTips( sceneId, selfId,nOdds)
	--0 1 2 5 4 3
	local GemNumber = LuaFnGetAvailableItemCount(sceneId, selfId,itemId1)
	local GemNeedNumber = 0
	if nSel == 0 then
		GemNeedNumber = 5
	elseif nSel == 1 then
		GemNeedNumber = 4
	elseif nSel == 2 then
		GemNeedNumber = 3
	end
	if GemNumber < GemNeedNumber then
		x900011_NotifyTips( sceneId, selfId,format("宝石数量不足%s颗，请确认后再尝试。",tostring(GemNeedNumber)))
		return
	end
	local nGemTransfur = GetBagItemTransfer( sceneId, selfId, g_GemTablePos ) --宝石trans
	local nItemTransfur = GetBagItemTransfer( sceneId, selfId, g_ItemBagIndex ) --合成符trans
	if nOdds == 100 then
		local ret = LuaFnDelAvailableItem(sceneId,selfId,itemId1,GemNeedNumber)
		  if ret ~= 1 then
		  x900011_NotifyTips( sceneId, selfId,"物品已锁定")
		    return
		  end
		if g_ItemBagIndex ~= -1 then
		    local ret = LuaFnDelAvailableItem(sceneId,selfId,itemId2,1)
			  if ret ~= 1 then
			  x900011_NotifyTips( sceneId, selfId,"物品已锁定")
			  return
			  end
		end --先删除，这样就不检查背包空间了
		local nNewPos = TryRecieveItem( sceneId, selfId, itemId1 + 100000 , 1 )
		LuaFnCostMoneyWithPriority( sceneId, selfId, tonumber(x900011_g_RuleTable[GemLevel].MoneyCost));
		LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
		x900011_NotifyTips( sceneId, selfId, "合成成功" )
		x900011_NotifyTips( sceneId, selfId, "你合成了一个"..GetItemName(sceneId,itemId1 + 100000) )
		if GemLevel >= 3 then
			local strText = format("#{_INFOUSR%s}#H把#G"..GemNeedNumber.."颗#{_INFOMSG%s}#H和1枚#{_INFOMSG%s}#H交给宝石工匠后，只见那工匠运刀如神，片刻间便将1颗闪闪发光的#{_INFOMSG%s}#H交还给#{_INFOUSR%s}#H，真是羡煞旁人。"
							,GetName(sceneId,selfId)
							,nGemTransfur
							,nItemTransfur
							,GetBagItemTransfer(sceneId,selfId,nNewPos)
							,GetName(sceneId,selfId)) 
	        BroadMsgByChatPipe(sceneId, selfId, strText, 4)
		end
	else
		local t1 = random(1,100)
		if t1 <= nOdds then
			local ret = LuaFnDelAvailableItem(sceneId,selfId,itemId1,GemNeedNumber)
			if ret ~= 1 then
			x900011_NotifyTips( sceneId, selfId,"物品已锁定")
			  return
			end
			if g_ItemBagIndex ~= -1 then
		        local ret = LuaFnDelAvailableItem(sceneId,selfId,itemId2,1)
				 if ret ~= 1 then
				 x900011_NotifyTips( sceneId, selfId,"物品已锁定")
				 return
				 end
		    end--先删除，这样就不检查背包空间了
			local nNewPos = TryRecieveItem( sceneId, selfId, itemId1 + 100000 , 1 )
			LuaFnCostMoneyWithPriority( sceneId, selfId, tonumber(x900011_g_RuleTable[GemLevel].MoneyCost));
			LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
			x900011_NotifyTips( sceneId, selfId, "合成成功" )
			x900011_NotifyTips( sceneId, selfId, format("你合成了一个%s","#{_ITEM"..tostring(itemId1 + 100000).."}") )
			if GemLevel >= 3 then
				local strText = format("#{_INFOUSR%s}#H把#G"..GemNeedNumber.."颗#{_INFOMSG%s}#H和1枚#{_INFOMSG%s}#H交给宝石工匠后，只见那工匠运刀如神，片刻间便将1颗闪闪发光的#{_INFOMSG%s}#H交还给#{_INFOUSR%s}#H，真是羡煞旁人。"
							,GetName(sceneId,selfId)
							,nGemTransfur
							,nItemTransfur
							,GetBagItemTransfer(sceneId,selfId,nNewPos)
							,GetName(sceneId,selfId)) 
				BroadMsgByChatPipe(sceneId, selfId, strText, 4)
            end
		else
			local ret = LuaFnDelAvailableItem(sceneId,selfId,itemId1,GemNeedNumber)
			  if ret ~= 1 then
			  x900011_NotifyTips( sceneId, selfId,"物品已锁定")
			    return
			  end
			if g_ItemBagIndex ~= -1 then
				local ret = LuaFnDelAvailableItem(sceneId,selfId,itemId2,1)
				 if ret ~= 1 then
				 x900011_NotifyTips( sceneId, selfId,"物品已锁定")
				 return
				 end
		    end
			LuaFnCostMoneyWithPriority( sceneId, selfId, tonumber(x900011_g_RuleTable[GemLevel].MoneyCost));
			x900011_NotifyTips( sceneId, selfId, "合成失败" )
			if GemLevel >= 3 then
				local strText = format("#{_INFOUSR%s0}#H经过一番努力，不但没有成功合成出".."#{_ITEM"..tostring(itemId1 + 100000).."}".."，反而白白损失了"..GemNeedNumber.."颗#{_ITEM"..tostring(itemId1).."}可惜可惜啊！",GetName(sceneId,selfId)) 
				BroadMsgByChatPipe(sceneId, selfId, strText, 4)
		    end
		end
	end
end
--**********************************
--获取宝石等级
--**********************************
function GetGemLevel(ID)
	local GemLevel = floor(mod(ID,10000000) / 100000)
	return GemLevel
end


--**********************************
--宝石镶嵌摘除
--**********************************
function x900011_OnLogin_BS(sceneId, selfId,posUI,posBag,posMite,Selected)
	
	if not posUI or not posBag then  return  end
	if posUI ==1 then   --拆除宝石用
		if posBag <0 or posBag >29 then return end
		      local disibaoshi =0
              local equipMaxGemCount = GetBagGemCount( sceneId, selfId, posBag )
			  if equipMaxGemCount ==4 then 
				disibaoshi = GetGemEmbededType( sceneId, selfId, posBag, 3 )		
			  end
            if disibaoshi ==-1 then  disibaoshi =0 end
	       BeginUICommand( sceneId )  --主控刷新界面
		   UICommand_AddInt( sceneId, disibaoshi )
	       EndUICommand( sceneId )
	       DispatchUICommand( sceneId, selfId,  201902177)
		return
	end

	if posUI ==3 then   --升级宝石用
		if posBag <0 or posBag >29 then return end
			 BeginUICommand( sceneId )  --主控刷新界面
		     for i=1, 4 do 
			  local	disibaoshi = GetGemEmbededType( sceneId, selfId, posBag, i-1)		
                if disibaoshi ==-1 then  disibaoshi =0 end
			  UICommand_AddInt( sceneId, disibaoshi )	
	        end
		   
	       EndUICommand( sceneId )
	       DispatchUICommand( sceneId, selfId,  201902178)
		return
	end	
	if posUI ==4 then
	  x900011_BSzhuanhuan(sceneId, selfId,posBag,posMite,Selected)
		return
	end
	if posUI ==5 then  --合成材料
	  x900011_CaiLiaoCompound(sceneId, selfId,posBag,posMite,Selected)
		return
	end	
end
