--宝石转换
--**********************************
function x900011_BSzhuanhuan(sceneId, selfId,posBag,posMite,Selected)
	if not posBag or posBag <0 or  not posMite or posMite<0 or not Selected or Selected<1 then  return  end
	local itemIndex =LuaFnGetItemTableIndexByIndex( sceneId, selfId,posBag )
	local itemcailiao= LuaFnGetItemTableIndexByIndex( sceneId, selfId,posMite )
	local   itemIndexstr = GetBagItemTransfer( sceneId, selfId, posBag )
	if floor( itemIndex / 10000000 ) ~= 5 then
	    x900011_NotifyTips( sceneId, selfId, "这里只能放入宝石"..itemIndex )	
		return 
	end
	if itemcailiao ~= 30000004 then  --物品材料ID
	 x900011_NotifyTips( sceneId, selfId, "材料不对或已经枷锁" )	
	return
	end
	if  LuaFnGetAvailableItemCount(sceneId, selfId, itemIndex) <1 then 
		x900011_NotifyTips( sceneId, selfId, "宝石不对或已经枷锁" )
		return
	end	
	if  LuaFnGetAvailableItemCount(sceneId, selfId, itemcailiao) <1 then 
		x900011_NotifyTips( sceneId, selfId, "材料不对或已经枷锁" )
		return
	end
	if YuanBao(sceneId,selfId,-1,3,0) <500 then 
		x900011_NotifyTips( sceneId, selfId, "元宝不足500个" )
		return
	end
	local nType=LuaFnGetItemType( itemIndex )
	local nLevel=GetItemQuality( itemIndex )
	local g_Type =0 
	if nType == 21 or nType == 2 or nType == 12 then 
	g_Type=1
	else
	g_Type=2
	end
	if g_Type ==0 then  return end
	if g_Type ==1 and  Selected >4 then 
		x900011_NotifyTips( sceneId, selfId, "选择错误" )
		return
	end
	if g_Type ==2 and  Selected >13 then 
		x900011_NotifyTips( sceneId, selfId, "选择错误" )
		return
	end	
	
	if g_Type == 1 then 
		local nSelected=Selected
		local n_itemIndex=floor( itemIndex / 10 )
		if mod(itemIndex,10) >4 then 
		nSelected=	Selected+4
		end
		local newitemIndex = tostring(n_itemIndex)..tostring(nSelected)
		newitemIndex=tonumber(newitemIndex)
		if strlen(newitemIndex) ~= 8 then
			x900011_NotifyTips( sceneId, selfId, "重试" ) 
			return
		end
		if LuaFnDelAvailableItem(sceneId,selfId,itemIndex,1) ~= 1 then 
			x900011_NotifyTips( sceneId, selfId, "宝石删除失败" )
			return
		end
		if LuaFnDelAvailableItem(sceneId,selfId,itemcailiao,1) ~= 1 then 
			x900011_NotifyTips( sceneId, selfId, "物品删除失败" )
			return
		end		
		if YuanBao(sceneId,selfId,-1,2,500) == -1 then 
			x900011_NotifyTips( sceneId, selfId, "元宝删除失败" )
			return
		end		
		local nposBag= TryRecieveItem( sceneId, selfId, newitemIndex, 1 )
		if nposBag ~= -1 then 
			LuaFnItemBind( sceneId, selfId, nposBag);
		end
		local   itemIndexstr1 = GetBagItemTransfer( sceneId, selfId, nposBag )
	   x900011_NotifyTips( sceneId, selfId, "宝石转换成功")	
	   LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0)
       local str = format( "#{_INFOUSR%s}#P使用宝石转换符施展乾坤大挪移将#{_INFOMSG%s1}瞬间变成了一颗全新的#{_INFOMSG%s2}#H。", GetName( sceneId, selfId), itemIndexstr, itemIndexstr1)
       BroadMsgByChatPipe( sceneId, selfId,str, 4 )		
	elseif g_Type == 2 then
	    local n_BaoShi={"01001","01002","03001","04002","11001","11002","13001","13002","13003","13004","13005","13006","14001",}
		local nSelected=Selected
		if nSelected<1 or nSelected >13 then 
		x900011_NotifyTips( sceneId, selfId, "重新选择" ) 	
		return
		end
		if n_BaoShi[nSelected] == nil then 
		x900011_NotifyTips( sceneId, selfId, "重新选择" ) 		
		return
		end
		local n_itemIndex=floor( itemIndex / 100000 )
		local newitemIndex = tostring(n_itemIndex)..tostring(n_BaoShi[nSelected])
		newitemIndex=tonumber(newitemIndex)
		if strlen(newitemIndex) ~= 8 then
			x900011_NotifyTips( sceneId, selfId, "重试" ) 
			return
		end
		if LuaFnDelAvailableItem(sceneId,selfId,itemIndex,1) ~= 1 then 
			x900011_NotifyTips( sceneId, selfId, "宝石删除失败" )
			return
		end
		if LuaFnDelAvailableItem(sceneId,selfId,itemcailiao,1) ~= 1 then 
			x900011_NotifyTips( sceneId, selfId, "物品删除失败" )
			return
		end		
		if YuanBao(sceneId,selfId,-1,2,500) == -1 then 
			x900011_NotifyTips( sceneId, selfId, "元宝删除失败" )
			return
		end		
		local nposBag= TryRecieveItem( sceneId, selfId, newitemIndex, 1 )
		if nposBag ~= -1 then 
			LuaFnItemBind( sceneId, selfId, nposBag);
		end
		local   itemIndexstr1 = GetBagItemTransfer( sceneId, selfId, nposBag )
	   x900011_NotifyTips( sceneId, selfId, "宝石转换成功")	
	   LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0)
      local str = format( "#{_INFOUSR%s}#P使用宝石转换符施展乾坤大挪移将#{_INFOMSG%s1}瞬间变成了一颗全新的#{_INFOMSG%s2}#H。", GetName( sceneId, selfId), itemIndexstr, itemIndexstr1)
       BroadMsgByChatPipe( sceneId, selfId,str, 4 )			
	end

end
